 * src/board_hooks_k7.c
 *
 * Strong-symbol board hooks for KICKPI K7 + openvela.
 * Fill the four TODOs with your ES8388 / VS6621SR80 / offline ASR APIs.
 * Until then this file still links, but voicelink will enter Error (-ENOSYS).
 *
 * Do not call Wi-Fi connect from this file.
 ****************************************************************************/

#include "voicelink/board_hooks.h"

#include <errno.h>
#include <string.h>
#include <syslog.h>

int voicelink_board_tts_speak(const char* utf8_text)
{
  if (utf8_text == NULL)
    {
      return -EINVAL;
    }

  /* TODO: UTF-8 text -> TTS -> ES8388 I2S speaker. Block until playback ends. */
  syslog(LOG_ERR, "voicelink: tts_speak not wired: %s\n", utf8_text);
  return -ENOSYS;
}

int voicelink_board_tts_stop(void)
{
  /* TODO: stop current ES8388 playback immediately. */
  return 0;
}

int voicelink_board_wifi_scan(struct voicelink_ap* aps, size_t capacity,
                             size_t* count)
{
  if (aps == NULL || count == NULL || capacity == 0)
    {
      return -EINVAL;
    }

  *count = 0;

  /* TODO: VS6621SR80 scan only. Fill ssid (UTF-8), rssi (dBm), secured (0/1).
   * Never connect. */
  syslog(LOG_ERR, "voicelink: wifi_scan not wired\n");
  return -ENOSYS;
}

int voicelink_board_asr_next(enum voicelink_grammar grammar, char* utf8_text,
                             size_t capacity)
{
  if (utf8_text == NULL || capacity == 0)
    {
      return -EINVAL;
    }

  memset(utf8_text, 0, capacity);

